/**
 * Proof Package rendering.
 *
 * The package is the reviewer-facing projection of the same facts the Proof
 * Graph holds, ordered for a human rather than for the query engine (PRD DP-01).
 * Nothing here is authored by a model: the summary is assembled from the data,
 * so it can be regenerated byte-for-byte from the graph and cannot drift into a
 * claim the evidence does not support (PRD DP-01, DP-03).
 */

import {
  crockfordBase32,
  proofChangesSchema,
  proofPackageSchema,
  type CapabilityLease,
  type EvidenceRecord,
  type OutcomeContract,
  type ProofGraph,
  type ProofPackage,
  type RedactionMode,
} from "@keystone/schemas";

import { checkPaths } from "../scope/scope.ts";

export interface RenderProofPackageInput {
  readonly graph: ProofGraph;
  readonly contract: OutcomeContract;
  readonly changedPaths: readonly string[];
  readonly diffArtifactId?: string;
  readonly evidence: readonly EvidenceRecord[];
  readonly projectRules?: readonly { factId: string; statement: string }[];
  readonly contextDecisions?: readonly { planId: string; stepId: string; tokensUsed: number; cacheHits: number; note: string }[];
  readonly modelRoutes?: readonly { role: string; modelId: string; provider: string }[];
  readonly leases?: readonly CapabilityLease[];
  readonly interventions?: readonly { interventionId: string; trigger: string; decision: string; rationale: string }[];
  readonly branchRationale?: string;
  readonly redaction?: "none" | "metadata_only";
  readonly environment?: {
    nodeVersion?: string;
    platform?: string;
    workspaceSnapshotId?: string;
    workspaceFingerprint?: string;
  };
}

/**
 * Deterministic package id, derived from the graph hash via Crockford base32 so
 * that re-rendering the same proof always yields the same id — a package is
 * content-addressed, not time-stamped (PRD DP-03, NFR-REL-05).
 */
function packageIdFrom(graphHash: string): string {
  const bytes = new Uint8Array(graphHash.length / 2);
  for (let index = 0; index < bytes.length; index += 1) {
    bytes[index] = Number.parseInt(graphHash.slice(index * 2, index * 2 + 2), 16);
  }
  return `pkg.${crockfordBase32(bytes).slice(0, 26).toLowerCase()}`;
}

function buildSummary(input: {
  contract: OutcomeContract;
  outcome: ProofGraph["decision"]["outcome"];
  conditionResults: ProofGraph["decision"]["conditionResults"];
  changedPaths: readonly string[];
  residualRisks: readonly string[];
}): string {
  const required = input.conditionResults.filter((result) => result.required);
  const failed = required.filter((result) => !result.satisfied);
  const passed = required.length - failed.length;

  const count = input.changedPaths.length;
  const sample = input.changedPaths.slice(0, 5).map((path) => `"${path}"`).join(", ");
  const more = count > 5 ? ` and ${count - 5} more` : "";

  const parts: string[] = [`Goal: ${input.contract.goal}.`];
  parts.push(
    count === 0
      ? "No files were changed."
      : `The change touched ${count} file${count === 1 ? "" : "s"} (${sample}${more}).`,
  );

  if (input.outcome === "proven") {
    parts.push(
      `Completion is proven: all ${required.length} required condition(s) are satisfied by evidence at the required level.`,
    );
  } else if (failed.length > 0) {
    parts.push(
      `Completion is not proven: ${passed} of ${required.length} required condition(s) are satisfied; ` +
        `still open: ${failed.slice(0, 5).map((result) => result.conditionId).join(", ")}` +
        `${failed.length > 5 ? ", ..." : ""}.`,
    );
    const codes = [...new Set(failed.map((result) => result.reasonCode))];
    parts.push(`Blocking reason(s): ${codes.join(", ")}.`);
  } else {
    parts.push(
      "Completion is not proven: every required condition is satisfied, but the change set or its evidence is not yet consistent.",
    );
  }

  if (input.residualRisks.length > 0) {
    parts.push(
      `Residual risk: ${input.residualRisks.slice(0, 3).join("; ")}` +
        `${input.residualRisks.length > 3 ? "; ..." : ""}.`,
    );
  }

  return parts.join(" ").slice(0, 8000);
}

export function renderProofPackage(input: RenderProofPackageInput): ProofPackage {
  const { graph, contract } = input;
  const decision = graph.decision;
  const redaction: RedactionMode = input.redaction ?? "none";
  const metadataOnly = redaction === "metadata_only";
  const evidenceNodes = new Map(
    graph.nodes.filter((node) => node.kind === "evidence").map((node) => [node.refId, node]),
  );
  const projectedStatus = (record: EvidenceRecord): EvidenceRecord["status"] => {
    const node = evidenceNodes.get(record.evidenceId);
    if (record.status === "invalid" || node === undefined || node.status === "invalid" || node.status === "unsupported") {
      return "invalid";
    }
    return record.status === "partially_invalid" || node.status === "pending" ? "partially_invalid" : "valid";
  };

  const scopeCheck = checkPaths(input.changedPaths, "write", contract.scope);
  const changes = proofChangesSchema.parse({
    changedFileCount: input.changedPaths.length,
    changedPaths: [...input.changedPaths],
    ...(input.diffArtifactId === undefined ? {} : { diffArtifactId: input.diffArtifactId }),
    withinScope: scopeCheck.violations.length === 0,
    scopeViolations: [...scopeCheck.violations].slice(0, 256),
  });

  // Explicitly not verified: auxiliary conditions that are not satisfied, and
  // any observation the verifier could not fully evaluate (PRD DP-01).
  const unverified: string[] = decision.reasons
    .filter(reason => reason.code === "pending")
    .map(reason => reason.detail);
  for (const result of decision.conditionResults) {
    if (!result.required && !result.satisfied) {
      unverified.push(
        `auxiliary condition ${result.conditionId} is not satisfied (${result.reasonCode}): ${result.description}`,
      );
    }
  }
  for (const record of input.evidence) {
    if (projectedStatus(record) !== "valid") {
      unverified.push(
        `evidence ${record.evidenceId} is not current support: ${evidenceNodes.get(record.evidenceId)?.reason ?? "not admitted by the proof graph"}`,
      );
    }
    const incomplete = record.observation.incomplete ?? [];
    if (incomplete.length > 0) {
      unverified.push(`evidence ${record.evidenceId} left items unresolved: ${incomplete.join("; ")}`);
    }
  }

  const partiallyInvalidEvidence = new Set(
    input.evidence
      .filter((record) => projectedStatus(record) === "partially_invalid")
      .map((record) => record.evidenceId),
  );
  const residualRisks: string[] = [];
  for (const result of decision.conditionResults) {
    if (result.evidenceIds.some((id) => partiallyInvalidEvidence.has(id))) {
      residualRisks.push(
        `condition ${result.conditionId} rests on evidence that is only partially valid`,
      );
    }
  }
  if (contract.scope.unknown.length > 0) {
    residualRisks.push(
      `the contract still has unresolved scope areas: ${contract.scope.unknown.join(", ")}`,
    );
  }
  if (metadataOnly) {
    residualRisks.push("file contents were stripped from this package (metadata-only export)");
  }

  const reproduceCommands: string[] = [];
  const seenCommands = new Set<string>();
  for (const record of input.evidence) {
    const command = record.observation.command;
    if (command === undefined || command.trim() === "" || seenCommands.has(command)) continue;
    seenCommands.add(command);
    reproduceCommands.push(command);
    if (reproduceCommands.length >= 64) break;
  }

  const summary = buildSummary({
    contract,
    outcome: decision.outcome,
    conditionResults: decision.conditionResults,
    changedPaths: input.changedPaths,
    residualRisks,
  });
  const decisionDetail = decision.outcome === "not_proven"
    ? decision.reasons.map(reason => reason.detail).join(" ").slice(0, 2000)
    : "";

  return proofPackageSchema.parse({
    packageId: packageIdFrom(graph.contentHash),
    taskId: graph.taskId,
    contractId: graph.contractId,
    contractVersion: graph.contractVersion,
    branchId: graph.branchId,
    generatedAt: new Date().toISOString(),

    summary: (summary + (decisionDetail ? ` ${decisionDetail}` : "")).slice(0, 8000),
    goal: contract.goal,
    outcome: decision.outcome,

    changes,
    conditions: [...decision.conditionResults],
    evidenceIndex: input.evidence.map((record) => ({
      evidenceId: record.evidenceId,
      level: record.level,
      producerId: record.producer.id,
      producerVersion: record.producer.version,
      conditionIds: [...record.conditionIds],
      createdAt: record.createdAt,
      status: projectedStatus(record),
      independenceMode: record.independence.mode,
    })),

    projectRules: (input.projectRules ?? []).map((rule) => ({
      factId: rule.factId,
      statement: metadataOnly ? "<redacted>" : rule.statement,
    })),
    contextDecisions: (input.contextDecisions ?? []).map((entry) => ({
      planId: entry.planId,
      stepId: entry.stepId,
      tokensUsed: entry.tokensUsed,
      cacheHits: entry.cacheHits,
      note: metadataOnly ? "<redacted>" : entry.note,
    })),
    modelRoutes: (input.modelRoutes ?? []).map((route) => ({ ...route })),

    branchRationale: input.branchRationale ?? "",
    leases: (input.leases ?? []).map((lease) => ({
      leaseId: lease.leaseId,
      capability: lease.capability,
      resourceKind: lease.resource.kind,
      resourceValues: [...lease.resource.values],
      ...(lease.decisionRef === undefined ? {} : { decisionRef: lease.decisionRef }),
    })),
    interventions: (input.interventions ?? []).map((entry) => ({ ...entry })),

    unverified: unverified.slice(0, 256),
    residualRisks: residualRisks.slice(0, 256),
    reproduceCommands,

    redaction,
    proofGraphHash: graph.contentHash,
    environment: input.environment ?? {},
  }) as ProofPackage;
}
